      const rows = await db.all("SELECT * FROM supplier_import_lab_extracted_rows WHERE extraction_run_id=? AND session_id=? AND selected_for_future_use=1 AND included_in_supplier_total=1 AND status!='rejected' ORDER BY ordinal",run.id,run.session_id);
